// Intro deck round 2 (docs/DECISIONS.md "D2"; deck design §7): the figures draw a Lucide subset as plain paths in every
// output. server/src/intro-deck/icons.ts holds each icon as absolute M/L/C/Z path data in Lucide's 24 grid, generated by
// scripts/gen-deck-icons.ts from the lucide-react the web app uses (arcs, circles, ellipses and rounded corners as
// cubic Béziers). These tests check the data's form, the lookups (other names, the fallback), the placement in slide
// px, that the file and its notice are what the generator makes from node_modules today, and the converted curves
// against Lucide's own numbers.
import { describe, expect, test } from 'bun:test'
import fs from 'node:fs'
import path from 'node:path'
import { FALLBACK_ICON, ICON_NAMES, LUCIDE_VERSION, iconItems, iconPaths, knownIcon, resolveIcon, transformPath } from '../../server/src/intro-deck/icons'
import { DECK_ICON_NAMES, NOTICE_DIR, buildDeckIcons, lucideRoot, parsePath, readIcon, renderIconsFile, renderNotice, segsToD } from '../../scripts/gen-deck-icons'

const REPO = path.resolve(import.meta.dir, '../..')
const ARITY: Record<string, number> = { M: 2, L: 2, C: 6, Z: 0 }

/** "M x y L x y C … Z" → commands with their numbers; throws on anything else */
function commands(d: string): { c: string; v: number[] }[] {
  const out: { c: string; v: number[] }[] = []
  for (const tok of d.split(' ')) {
    if (tok in ARITY) out.push({ c: tok, v: [] })
    else {
      expect(tok).toMatch(/^-?\d+(?:\.\d{1,3})?$/)
      out[out.length - 1].v.push(Number(tok))
    }
  }
  return out
}
/** every coordinate pair (end and control points) of a path */
const pointsOf = (d: string) => commands(d).flatMap(({ v }) => v.flatMap((n, i) => (i % 2 ? [] : [[n, v[i + 1]] as [number, number]])))
const bbox = (ds: string[]) => {
  const p = ds.flatMap(pointsOf)
  return { x0: Math.min(...p.map(q => q[0])), y0: Math.min(...p.map(q => q[1])), x1: Math.max(...p.map(q => q[0])), y1: Math.max(...p.map(q => q[1])) }
}
/** points along every cubic of a path (t = 0.25, 0.5, 0.75) */
function curvePoints(d: string): [number, number][] {
  const out: [number, number][] = []
  let x = 0, y = 0
  for (const { c, v } of commands(d)) {
    if (c === 'C') {
      for (const t of [0.25, 0.5, 0.75]) {
        const a = (1 - t) ** 3, b = 3 * (1 - t) ** 2 * t, e = 3 * (1 - t) * t * t, f = t ** 3
        out.push([a * x + b * v[0] + e * v[2] + f * v[4], a * y + b * v[1] + e * v[3] + f * v[5]])
      }
    }
    if (v.length) { x = v[v.length - 2]; y = v[v.length - 1] }
  }
  return out
}

describe('the icon data', () => {
  test('every listed icon is absolute M/L/C/Z path data with finite numbers (3 decimals at most) inside the 24 grid', () => {
    expect(ICON_NAMES.length).toBeGreaterThanOrEqual(140)
    expect(ICON_NAMES.length).toBeLessThanOrEqual(200)
    expect([...ICON_NAMES]).toEqual([...new Set(ICON_NAMES)].sort())
    expect(ICON_NAMES).toContain(FALLBACK_ICON)
    for (const name of ICON_NAMES) {
      const paths = iconPaths(name)
      expect(paths.length, name).toBeGreaterThan(0)
      for (const d of paths) {
        const cmds = commands(d)
        expect(cmds[0].c, name).toBe('M')
        for (const { c, v } of cmds) {
          expect(v.length, `${name}: ${c}`).toBe(ARITY[c])
          for (const n of v) {
            expect(Number.isFinite(n), name).toBe(true)
            expect(n, name).toBeGreaterThanOrEqual(-2)
            expect(n, name).toBeLessThanOrEqual(26)
          }
        }
      }
    }
  })

  test('the design system\'s categories are all there, and the list the AI sees is the stored names', () => {
    for (const name of ['factory', 'cpu', 'memory-stick', 'server', 'car', 'truck', 'warehouse', 'coffee', 'bean', 'store', 'shopping-bag', 'package',
      'users', 'headset', 'handshake', 'graduation-cap', 'message-circle', 'megaphone', 'inbox', 'chart-column', 'database', 'layers',
      'shield-check', 'badge-check', 'clipboard-check', 'calendar-sync', 'refresh-cw', 'workflow', 'leaf', 'map-pin', 'mountain']) {
      expect(ICON_NAMES, name).toContain(name)
    }
    // every requested name is known (some under the name lucide-react stores them as)
    for (const name of DECK_ICON_NAMES) expect(knownIcon(name), name).toBe(true)
  })

  test('other names resolve to the icon they stand for; an unknown or empty name gives the fallback', () => {
    expect(resolveIcon('home')).toBe('house')
    expect(iconPaths('home')).toEqual(iconPaths('house'))
    expect(resolveIcon('building-2')).toBe('building-complex')
    expect(knownIcon('building-2')).toBe(true)
    expect(ICON_NAMES).not.toContain('home')
    // lucide-react's older names for a stored icon
    expect(resolveIcon('bar-chart-3')).toBe('chart-column')
    // the forms an AI may write
    expect(resolveIcon('Shopping Bag')).toBe('shopping-bag')
    expect(resolveIcon('shopping_bag')).toBe('shopping-bag')
    expect(resolveIcon('ShoppingBag')).toBe('shopping-bag')
    expect(resolveIcon(' factory ')).toBe('factory')
    const fallback = iconPaths(FALLBACK_ICON)
    for (const name of ['no-such-icon', '', '__proto__', 'constructor', 'toString', undefined]) {
      expect(iconPaths(name), String(name)).toEqual(fallback)
      if (name !== undefined) expect(knownIcon(name)).toBe(false)
    }
    // a caller cannot change the stored data through the returned list
    iconPaths('factory').push('M 0 0')
    expect(iconPaths('factory').includes('M 0 0')).toBe(false)
  })
})

describe('placing an icon on a slide', () => {
  test('transformPath scales about the origin and moves; anything but absolute M/L/C/Z is refused', () => {
    expect(transformPath('M 0 0 L 24 24 C 1 2 3 4 5 6 Z', 2, 10, 20)).toBe('M 10 20 L 58 68 C 12 24 16 28 20 32 Z')
    expect(transformPath('M 1.5 -0.25 L 3 3', 1 / 3, 0, 0)).toBe('M 0.5 -0.08 L 1 1')
    expect(() => transformPath('M 0 0 h 3', 1, 0, 0)).toThrow()
    expect(() => transformPath('M 0 0 A 1 1 0 0 1 2 2', 1, 0, 0)).toThrow()
  })

  test('iconItems puts the icon in the size × size box at (x, y), stroked, unfilled, one group', () => {
    const items = iconItems('factory', 100, 200, 48, '#112233')
    expect(items.length).toBe(iconPaths('factory').length)
    const b = bbox(items.map(i => i.d))
    expect(b.x0).toBeGreaterThanOrEqual(100); expect(b.x1).toBeLessThanOrEqual(148)
    expect(b.y0).toBeGreaterThanOrEqual(200); expect(b.y1).toBeLessThanOrEqual(248)
    for (const it of items) {
      expect(it.t).toBe('path')
      expect(it.fill).toBeUndefined()
      expect(it.stroke).toEqual({ color: '#112233', width: 3, cap: 'round', join: 'round' })
      expect(it.group).toBe('icon-factory-100-200')
    }
    // the ring of circle-dot is r 10 about (12, 12): at 48 px from (40, 60) it spans 44…84 × 64…104
    const ring = iconItems('circle-dot', 40, 60, 48, '#000')[1]
    expect(bbox([ring.d])).toEqual({ x0: 44, y0: 64, x1: 84, y1: 104 })
    // an unknown name draws the fallback, under its own group name
    const unknown = iconItems('no-such-icon', 40, 60, 48, '#000')
    expect(unknown.map(i => i.d)).toEqual(iconItems('circle-dot', 40, 60, 48, '#000').map(i => i.d))
    expect(unknown[0].group).toBe('icon-circle-dot-40-60')
  })

  test('the stroke scales with the size; a group can be given', () => {
    expect(iconItems('coffee', 0, 0, 64, '#000', 1.75)[0].stroke!.width).toBeCloseTo(1.75 * 64 / 24, 9)
    expect(iconItems('coffee', 0, 0, 24, '#000')[0].stroke!.width).toBe(1.5)
    expect(new Set(iconItems('coffee', 0, 0, 44, '#000', 1.5, 'step-2-icon').map(i => i.group))).toEqual(new Set(['step-2-icon']))
  })

  test('the same call gives the same items', () => {
    for (const name of ['factory', 'users', 'calendar-sync', 'nothing']) {
      expect(JSON.stringify(iconItems(name, 12.5, 7.25, 56, '#abcdef', 1.6))).toBe(JSON.stringify(iconItems(name, 12.5, 7.25, 56, '#abcdef', 1.6)))
    }
  })
})

describe('the generator', () => {
  test('icons.ts and the notice are what scripts/gen-deck-icons.ts makes from the installed lucide-react', () => {
    const root = lucideRoot()
    const b = buildDeckIcons(root)
    expect(b.version).toBe(LUCIDE_VERSION)
    expect(JSON.parse(fs.readFileSync(path.join(REPO, 'web/package.json'), 'utf8')).dependencies['lucide-react']).toBe(LUCIDE_VERSION)
    expect(b.missing).toEqual([])
    const file = path.join(REPO, 'server/src/intro-deck/icons.ts')
    const current = fs.readFileSync(file, 'utf8')
    // out of date: run `bun scripts/gen-deck-icons.ts`
    expect(renderIconsFile(b, current) === current).toBe(true)
    expect(fs.readFileSync(path.join(NOTICE_DIR, 'NOTICE.txt'), 'utf8')).toBe(renderNotice(b))
    expect(fs.readFileSync(path.join(NOTICE_DIR, 'LICENSE.txt'))).toEqual(fs.readFileSync(path.join(root, 'LICENSE')))
    expect(b.icons.map(([n]) => n)).toEqual([...ICON_NAMES])
    // the Feather-derived icons (MIT) are named in the file's header and the notice
    expect(b.feather).toContain('search')
    for (const n of b.feather) expect(current.slice(0, current.indexOf('import type'))).toContain(n)
  })

  test('the converter: relative commands, H/V/S/Q/T and packed arc flags become absolute M/L/C/Z', () => {
    expect(segsToD(parsePath('m2 2h4v4H2z'))).toBe('M 2 2 L 6 2 L 6 6 L 2 6 Z')
    // after Z a relative move starts from the subpath's start; implicit pairs after M are lines
    expect(segsToD(parsePath('M10 10 20 10z m5 5 l1 1'))).toBe('M 10 10 L 20 10 Z M 15 15 L 16 16')
    // S reflects the last control point; T reflects the last quadratic one (as cubics: 2/3 of the way)
    expect(segsToD(parsePath('M0 0c1 1 2 1 3 0s2-1 3 0'))).toBe('M 0 0 C 1 1 2 1 3 0 C 4 -1 5 -1 6 0')
    expect(segsToD(parsePath('M0 0Q3 3 6 0T12 0'))).toBe('M 0 0 C 2 2 4 2 6 0 C 8 -2 10 -2 12 0')
    // a half circle with packed flags ("0 110 0": large 1, sweep 1, then 10 0) ends where it should, on the circle
    const half = segsToD(parsePath('M0 0a5 5 0 1110 0'))
    expect(half.endsWith(' 10 0')).toBe(true)
    for (const [x, y] of curvePoints(half)) expect(Math.hypot(x - 5, y)).toBeCloseTo(5, 2)
  })

  test('converted curves lie on Lucide\'s own circles and ellipses', () => {
    const dir = path.join(lucideRoot(), 'dist/esm/icons')
    // circle-dot: <circle cx 12 cy 12 r 10>
    expect(readIcon(dir, 'circle-dot')!.nodes[1]).toEqual(['circle', { cx: '12', cy: '12', r: '10' }])
    const ring = iconPaths('circle-dot')[1]
    expect(bbox([ring])).toEqual({ x0: 2, y0: 2, x1: 22, y1: 22 })
    for (const [x, y] of curvePoints(ring)) expect(Math.hypot(x - 12, y - 12)).toBeCloseTo(10, 2)
    // refresh-cw: "M3 12a9 9 0 0 1 9-9 …": a quarter of the circle r 9 about (12, 12)
    expect(readIcon(dir, 'refresh-cw')!.nodes[0][1].d.startsWith('M3 12a9 9 0 0 1 9-9')).toBe(true)
    const arc = iconPaths('refresh-cw')[0]
    expect(arc.startsWith('M 3 12 C ')).toBe(true)
    for (const [x, y] of curvePoints(arc.split(' L ')[0]).slice(0, 3)) expect(Math.hypot(x - 12, y - 12)).toBeCloseTo(9, 2)
    // database: "M3 5V19A9 3 0 0 0 21 19V5": the lower half of the ellipse rx 9, ry 3 about (12, 19)
    const can = iconPaths('database')[1]
    const onEllipse = curvePoints(can)
    expect(onEllipse.length).toBeGreaterThan(0)
    for (const [x, y] of onEllipse) expect(((x - 12) / 9) ** 2 + ((y - 19) / 3) ** 2).toBeCloseTo(1, 2)
    for (const [, y] of onEllipse) expect(y).toBeGreaterThanOrEqual(19)
    // calendar: <rect x 3 y 3 width 18 height 18 rx 2>: the box, with corners rounded inside it
    expect(bbox([iconPaths('calendar')[2]])).toEqual({ x0: 3, y0: 3, x1: 21, y1: 21 })
    expect(iconPaths('calendar')[2].startsWith('M 5 3 L 19 3 C ')).toBe(true)
  })
})
